import dgetrf = require( './index' );


// TESTS //

{
	const A = new Float64Array( 9 );
	const IPIV = new Int32Array( 3 );

	dgetrf( 3, 3, A, 3, IPIV ); // $ExpectType number
}

{
	const A = new Float64Array( 9 );
	const IPIV = new Int32Array( 3 );

	dgetrf.ndarray( 3, 3, A, 1, 3, 0, IPIV, 1, 0 ); // $ExpectType number
}

{
	const A = new Float64Array( 9 );
	const IPIV = new Int32Array( 3 );

	dgetrf( '3', 3, A, 3, IPIV ); // $ExpectError
	dgetrf( 3, 3, A, 3, new Float64Array( 3 ) ); // $ExpectError
	dgetrf( 3, 3, new Int32Array( 9 ), 3, IPIV ); // $ExpectError
	dgetrf( 3, 3, A, '3', IPIV ); // $ExpectError
	dgetrf( 3, 3, A, 3, IPIV, 0 ); // $ExpectError
}

{
	const A = new Float64Array( 9 );
	const IPIV = new Int32Array( 3 );

	dgetrf.ndarray( '3', 3, A, 1, 3, 0, IPIV, 1, 0 ); // $ExpectError
	dgetrf.ndarray( 3, 3, new Int32Array( 9 ), 1, 3, 0, IPIV, 1, 0 ); // $ExpectError
	dgetrf.ndarray( 3, 3, A, '1', 3, 0, IPIV, 1, 0 ); // $ExpectError
	dgetrf.ndarray( 3, 3, A, 1, '3', 0, IPIV, 1, 0 ); // $ExpectError
	dgetrf.ndarray( 3, 3, A, 1, 3, '0', IPIV, 1, 0 ); // $ExpectError
	dgetrf.ndarray( 3, 3, A, 1, 3, 0, new Float64Array( 3 ), 1, 0 ); // $ExpectError
	dgetrf.ndarray( 3, 3, A, 1, 3, 0, IPIV, '1', 0 ); // $ExpectError
	dgetrf.ndarray( 3, 3, A, 1, 3, 0, IPIV, 1, '0' ); // $ExpectError
	dgetrf.ndarray( 3, 3, A, 1, 3, 0, IPIV, 1, 0, 10 ); // $ExpectError
}

{
	const A = new Float64Array( 9 );
	const IPIV = new Int32Array( 3 );

	dgetrf(); // $ExpectError
	dgetrf( 3 ); // $ExpectError
	dgetrf( 3, 3, A ); // $ExpectError
	dgetrf( 3, 3, A, 3 ); // $ExpectError
	dgetrf.ndarray(); // $ExpectError
	dgetrf.ndarray( 3, 3, A, 1, 3, 0, IPIV, 1 ); // $ExpectError
}
